// Config defines one deterministic three-node election simulation.
type Config struct {
	NodeIDs       []uint64
	Initial       []InitialNode
	TimeoutScript []int
}

// InitialNode provides durable state before a simulated start or restart.
type InitialNode struct {
	ID         uint64
	Persistent raft.Persistent
}

// NodeState describes a simulator node without exposing mutable state.
type NodeState struct {
	ID    uint64
	Alive bool
	State raft.State
}

// CampaignStats summarizes election and fault activity in a completed run.
type CampaignStats struct {
	DistinctLeaderPairs int
	DistinctLeaderTerms int
	Crashes             int
	CrashesAfterLeader  int
}

type slot struct {
	id      uint64
	node    *raft.Node
	durable raft.Persistent
	alive   bool
}

type queuedMessage struct {
	message raft.Message
}

type blockedLink struct {
	from uint64
	to   uint64
}

type leaderRecord struct {
	term uint64
	id   uint64
}

// Simulator owns virtual time, fault scheduling, network delivery, and RNG.
type Simulator struct {
	seed               int64
	nowMS              uint64
	step               uint64
	rng                *randomSource
	slots              []slot
	queue              []queuedMessage
	blocked            []blockedLink
	leaders            []leaderRecord
	crashes            int
	crashesAfterLeader int
	trace              []string
	violation          error
}

// New creates a deterministic election simulator.
func New(seed int64, config Config) *Simulator {
	ids := append([]uint64(nil), config.NodeIDs...)
	sort.Slice(ids, func(left, right int) bool { return ids[left] < ids[right] })
	if len(ids) == 0 {
		ids = []uint64{1, 2, 3}
	}
	sim := &Simulator{
		seed: seed,
		rng:  newRandomSource(seed, config.TimeoutScript),
	}
	for _, id := range ids {
		persistent := initialPersistent(id, config.Initial)
		sim.slots = append(sim.slots, slot{
			id:      id,
			durable: persistent.Clone(),
			alive:   true,
		})
	}
	for index := range sim.slots {
		sim.slots[index].node = sim.newNode(sim.slots[index].id, sim.slots[index].durable)
	}
	return sim
}

// Tick advances one targeted virtual-time round and one node's Raft timer.
func (s *Simulator) Tick(id uint64) bool {
	s.nowMS += 100
	return s.tick(id)
}

func (s *Simulator) tick(id uint64) bool {
	index := s.indexOf(id)
	if index < 0 || !s.slots[index].alive || s.violation != nil {
		return false
	}
	output := s.slots[index].node.Tick()
	s.applyOutput(index, output)
	state := s.slots[index].node.State()
	s.record(id, "tick", 0, id, state.Term, state.Role.String())
	return true
}

// TickAll advances every live node in sorted node-ID order.
func (s *Simulator) TickAll() {
	if s.violation != nil {
		return
	}
	s.nowMS += 100
	for _, current := range s.slots {
		if s.violation != nil {
			return
		}
		s.tick(current.id)
	}
}

// Deliver delivers the oldest matching queued message.
func (s *Simulator) Deliver(from, to uint64, kind raft.MessageType) bool {
	queueIndex := -1
	for index, queued := range s.queue {
		if queued.message.From == from && queued.message.To == to && queued.message.Type == kind {
			queueIndex = index
			break
		}
	}
	if queueIndex < 0 || s.violation != nil {
		return false
	}
	s.deliverAt(queueIndex)
	return true
}

// DeliverAll delivers queued messages in FIFO order until the queue is empty.
func (s *Simulator) DeliverAll() {
	for len(s.queue) > 0 && s.violation == nil {
		s.deliverAt(0)
	}
}

// Drop removes the oldest matching queued message.
func (s *Simulator) Drop(from, to uint64, kind raft.MessageType) bool {
	for index, queued := range s.queue {
		if queued.message.From == from && queued.message.To == to && queued.message.Type == kind {
			s.queue = append(s.queue[:index], s.queue[index+1:]...)
			s.record(to, "drop", from, to, queued.message.Term, queued.message.Type.String())
			return true
		}
	}
	return false
}

// Crash discards volatile node state while retaining only its durable state.
func (s *Simulator) Crash(id uint64) bool {
	index := s.indexOf(id)
	if index < 0 || !s.slots[index].alive || s.violation != nil {
		return false
	}
	s.slots[index].node = nil
	s.slots[index].alive = false
	s.crashes++
	if len(s.leaders) > 0 {
		s.crashesAfterLeader++
	}
	s.record(id, "crash", id, 0, s.slots[index].durable.Term, "durable_state_retained")
	return true
}

// Restart recreates a crashed node as a follower from its last durable state.
func (s *Simulator) Restart(id uint64) bool {
	index := s.indexOf(id)
	if index < 0 || s.slots[index].alive || s.violation != nil {
		return false
	}
	s.slots[index].node = s.newNode(id, s.slots[index].durable)
	s.slots[index].alive = true
	s.record(id, "restart", 0, id, s.slots[index].durable.Term, "durable_state_restored")
	return true
}

// Partition blocks all messages between the supplied node groups.
func (s *Simulator) Partition(left, right []uint64) {
	for _, from := range left {
		for _, to := range right {
			s.block(from, to)
			s.block(to, from)
		}
	}
	s.record(0, "partition", 0, 0, 0, "links_blocked")
}

// Heal restores delivery across every previously blocked link.
func (s *Simulator) Heal() {
	s.blocked = nil
	s.record(0, "heal", 0, 0, 0, "all_links_restored")
}

// RunNoFault drives ticks and FIFO delivery without introducing faults.
func (s *Simulator) RunNoFault(maxTicks int) error {
	for tick := 0; tick < maxTicks && s.violation == nil; tick++ {
		s.TickAll()
		s.DeliverAll()
	}
	return s.violation
}

// RunRandom drives a deterministic mix of ticks, delivery, and fault events.
func (s *Simulator) RunRandom(steps int) error {
	for step := 0; step < steps && s.violation == nil; step++ {
		s.randomEvent()
	}
	return s.violation
}

// Leader returns the first live leader in sorted node-ID order.
func (s *Simulator) Leader() (uint64, uint64, bool) {
	for _, current := range s.slots {
		if current.alive && current.node.State().Role == raft.Leader {
			state := current.node.State()
			return current.id, state.Term, true
		}
	}
	return 0, 0, false
}

// Nodes returns node state in sorted node-ID order.
func (s *Simulator) Nodes() []NodeState {
	states := make([]NodeState, 0, len(s.slots))
	for _, current := range s.slots {
		state := raft.State{ID: current.id}
		if current.alive {
			state = current.node.State()
		}
		states = append(states, NodeState{ID: current.id, Alive: current.alive, State: state})
	}
	return states
}

// Trace returns a copy of the deterministic event trace.
func (s *Simulator) Trace() []string {
	return append([]string(nil), s.trace...)
}

// Hash returns the SHA-256 of the full trace.
func (s *Simulator) Hash() string {
	sum := sha256.Sum256([]byte(strings.Join(s.trace, "\n")))
	return fmt.Sprintf("%x", sum)
}

// Error returns an ElectionSafety violation, if one occurred.
func (s *Simulator) Error() error {
	return s.violation
}

// Stats returns deterministic campaign coverage statistics.
func (s *Simulator) Stats() CampaignStats {
	terms := make([]uint64, 0, len(s.leaders))
	for _, leader := range s.leaders {
		known := false
		for _, term := range terms {
			if term == leader.term {
				known = true
				break
			}
		}
		if !known {
			terms = append(terms, leader.term)
		}
	}
	return CampaignStats{
		DistinctLeaderPairs: len(s.leaders),
		DistinctLeaderTerms: len(terms),
		Crashes:             s.crashes,
		CrashesAfterLeader:  s.crashesAfterLeader,
	}
}

// HasLeaderInTerm reports whether a leader was observed in the given term.
func (s *Simulator) HasLeaderInTerm(term uint64) bool {
	for _, leader := range s.leaders {
		if leader.term == term {
			return true
		}
	}
	return false
}

func (s *Simulator) newNode(id uint64, persistent raft.Persistent) *raft.Node {
	return raft.NewNode(raft.Config{
		ID:         id,
		Peers:      s.peerIDs(id),
		Rand:       s.rng,
		Persistent: persistent.Clone(),
	})
}

func (s *Simulator) applyOutput(index int, output raft.Output) {
	if output.Persist != nil {
		s.slots[index].durable = output.Persist.Clone()
	}
	for _, message := range output.Msgs {
		s.queue = append(s.queue, queuedMessage{message: message})
	}
}

func (s *Simulator) deliverAt(queueIndex int) {
	queued := s.queue[queueIndex]
	s.queue = append(s.queue[:queueIndex], s.queue[queueIndex+1:]...)
	target := s.indexOf(queued.message.To)
	if target < 0 || !s.slots[target].alive || s.isBlocked(queued.message.From, queued.message.To) {
		s.record(queued.message.To, "drop", queued.message.From, queued.message.To, queued.message.Term, queued.message.Type.String())
		return
	}
	output := s.slots[target].node.Step(queued.message)
	s.applyOutput(target, output)
	s.record(queued.message.To, "deliver", queued.message.From, queued.message.To, queued.message.Term, queued.message.Type.String())
}

func (s *Simulator) randomEvent() {
	switch draw := s.rng.Intn(100); {
	case draw < 45:
		s.randomTick()
	case draw < 75:
		if len(s.queue) == 0 {
			s.randomTick()
			return
		}
		s.deliverAt(s.rng.Intn(len(s.queue)))
	case draw < 79:
		s.randomDrop()
	case draw < 83:
		s.randomDuplicate()
	case draw < 87:
		s.randomReorder()
	case draw < 90:
		s.randomCrash()
	case draw < 92:
		s.randomRestart()
	case draw < 95:
		s.randomPartition()
	default:
		s.Heal()
	}
}

func (s *Simulator) randomTick() {
	index := s.randomLiveIndex()
	if index < 0 {
		s.randomRestart()
		return
	}
	s.Tick(s.slots[index].id)
}

func (s *Simulator) randomDrop() {
	if len(s.queue) == 0 {
		s.randomTick()
		return
	}
	index := s.rng.Intn(len(s.queue))
	queued := s.queue[index]
	s.queue = append(s.queue[:index], s.queue[index+1:]...)
	s.record(queued.message.To, "drop", queued.message.From, queued.message.To, queued.message.Term, queued.message.Type.String())
}

func (s *Simulator) randomDuplicate() {
	if len(s.queue) == 0 {
		s.randomTick()
		return
	}
	queued := s.queue[s.rng.Intn(len(s.queue))]
	s.queue = append(s.queue, queued)
	s.record(queued.message.To, "duplicate", queued.message.From, queued.message.To, queued.message.Term, queued.message.Type.String())
}

func (s *Simulator) randomReorder() {
	if len(s.queue) < 2 {
		s.randomTick()
		return
	}
	left := s.rng.Intn(len(s.queue))
	right := s.rng.Intn(len(s.queue))
	s.queue[left], s.queue[right] = s.queue[right], s.queue[left]
	s.record(0, "reorder", 0, 0, 0, "queue_positions_swapped")
}

func (s *Simulator) randomCrash() {
	index := s.randomLiveIndex()
	if index >= 0 {
		s.Crash(s.slots[index].id)
		return
	}
	s.record(0, "crash", 0, 0, 0, "no_live_node")
}

func (s *Simulator) randomRestart() {
	var crashed []uint64
	for _, current := range s.slots {
		if !current.alive {
			crashed = append(crashed, current.id)
		}
	}
	if len(crashed) > 0 {
		s.Restart(crashed[s.rng.Intn(len(crashed))])
		return
	}
	s.record(0, "restart", 0, 0, 0, "no_crashed_node")
}

func (s *Simulator) randomPartition() {
	if len(s.slots) < 2 {
		s.record(0, "partition", 0, 0, 0, "insufficient_nodes")
		return
	}
	index := s.rng.Intn(len(s.slots))
	left := []uint64{s.slots[index].id}
	right := make([]uint64, 0, len(s.slots)-1)
	for other, current := range s.slots {
		if other != index {
			right = append(right, current.id)
		}
	}
	s.Partition(left, right)
}

func (s *Simulator) randomLiveIndex() int {
	var live []int
	for index, current := range s.slots {
		if current.alive {
			live = append(live, index)
		}
	}
	if len(live) == 0 {
		return -1
	}
	return live[s.rng.Intn(len(live))]
}

func (s *Simulator) indexOf(id uint64) int {
	for index, current := range s.slots {
		if current.id == id {
			return index
		}
	}
	return -1
}

func (s *Simulator) peerIDs(id uint64) []uint64 {
	peers := make([]uint64, 0, len(s.slots)-1)
	for _, current := range s.slots {
		if current.id != id {
			peers = append(peers, current.id)
		}
	}
	return peers
}

func (s *Simulator) block(from, to uint64) {
	if !s.isBlocked(from, to) {
		s.blocked = append(s.blocked, blockedLink{from: from, to: to})
	}
}

func (s *Simulator) isBlocked(from, to uint64) bool {
	for _, link := range s.blocked {
		if link.from == from && link.to == to {
			return true
		}
	}
	return false
}

func (s *Simulator) record(node uint64, event string, from, to, term uint64, detail string) {
	s.step++
	s.trace = append(s.trace, fmt.Sprintf(
		"step=%d t=%d node=%d ev=%s from=%d to=%d term=%d detail=%s rng=%d",
		s.step, s.nowMS, node, event, from, to, term, detail, s.rng.lastDraw,
	))
	s.checkElectionSafety()
}

func (s *Simulator) checkElectionSafety() {
	if s.violation != nil {
		return
	}
	for _, current := range s.slots {
		if !current.alive || current.node.State().Role != raft.Leader {
			continue
		}
		state := current.node.State()
		knownLeader := false
		for _, leader := range s.leaders {
			if leader.term == state.Term && leader.id != current.id {
				s.violation = fmt.Errorf("ElectionSafety violation: leaders %d and %d in term %d; seed=%d; trace tail:\n%s", leader.id, current.id, state.Term, s.seed, strings.Join(s.traceTail(12), "\n"))
				return
			}
			if leader.term == state.Term && leader.id == current.id {
				knownLeader = true
			}
		}
		if !knownLeader {
			s.leaders = append(s.leaders, leaderRecord{term: state.Term, id: current.id})
		}
	}
}

func (s *Simulator) traceTail(limit int) []string {
	if len(s.trace) <= limit {
		return append([]string(nil), s.trace...)
	}
	return append([]string(nil), s.trace[len(s.trace)-limit:]...)
}

func initialPersistent(id uint64, initial []InitialNode) raft.Persistent {
	for _, node := range initial {
		if node.ID == id {
			return node.Persistent.Clone()
		}
	}
	return raft.Persistent{}
}

type randomSource struct {
	rng      *rand.Rand
	script   []int
	position int
	lastDraw int
}

func newRandomSource(seed int64, script []int) *randomSource {
	return &randomSource{
		rng:    rand.New(rand.NewSource(seed)),
		script: append([]int(nil), script...),
	}
}

func (r *randomSource) Intn(n int) int {
	if n <= 0 {
		panic("Intn called with non-positive bound")
	}
	if r.position < len(r.script) {
		value := r.script[r.position]
		r.position++
		if value < 0 || value >= n {
			panic("scripted random value outside Intn range")
		}
		r.lastDraw = value
		return value
	}
	r.lastDraw = r.rng.Intn(n)
	return r.lastDraw
}
